import {membershipActive,groupMembers} from '../create-join/model.js';
import {resolveQR,qrReference} from './qr.js';
export function createQRUI(context){
 function view(){const{s,actor,route,staticScreen,esc,device,name,money,fixture}=context(),result=route.reference?resolveQR(s,actor,route.reference,{paymentId:route.payment}):null,page=result?.page||route.page||'entry',screen=staticScreen('22',page),main=screen.querySelector('main,.content');main.querySelectorAll('.scope-card,.person-card,.qr-card,.qr-wrap').forEach(n=>n.remove());const sub=main.querySelector('.lead');if(sub)sub.textContent='Recognize an inert local reference, then explicitly hand off to its owner. Scanning never joins, shares, requests, signs or pays.';const title=main.querySelector('h1');const identity=main.querySelector('.person-copy b'),avatar=main.querySelector('.person-avatar');if(identity)identity.textContent=result?.id?name(s,result.id):actor==='self'?'You':name(s,actor);if(avatar)avatar.textContent=identity?.textContent.split(/\s+/).map(x=>x[0]).join('').slice(0,2)||'';const share=result?.id&&s.expansion.shares.find(r=>r.id===result.id),method=share&&s.expansion.methods.find(m=>m.id===share.methodId),invite=result?.id&&s.membership?.invitations.find(i=>i.id===result.id),g=invite&&s.groups.find(g=>g.id===invite.groupId);if(identity&&page==='receive-share')identity.textContent=name(s,share.owner);if(identity&&page.startsWith('invite'))identity.textContent=g.name;if(avatar&&!page.startsWith('invite'))avatar.textContent=identity?.textContent.split(/\s+/).map(x=>x[0]).join('').slice(0,2)||'';const meta=main.querySelector('.result-meta');if(meta&&page==='receive-share')meta.innerHTML=`<div class="meta-row"><span>Method scope</span><b>${esc(method.method+' · '+method.currency)}</b></div><div class="meta-row"><span>Next owner</span><b>Receive / Share</b></div>`;if(meta&&page.startsWith('invite')){const sub=main.querySelector('.person-copy span');if(sub)sub.textContent='Invited by '+name(s,invite.inviterId||'self');meta.innerHTML=`<div class="meta-row"><span>People</span><b>${groupMembers(s,g).length}</b></div><div class="meta-row"><span>Currency</span><b>${esc(g.currency)}</b></div><div class="meta-row"><span>Next owner</span><b>Invite / Join</b></div>`;}const party=page==='receive-share'?share.owner:page.startsWith('invite')?invite?.inviterId:result?.id;const walk=document.createTreeWalker(screen,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode())node.textContent=node.textContent.replaceAll('Maya',party?name(s,party):'the code owner');if(page==='settlement-match'){const p=s.gateC.payments.find(p=>p.id===route.payment),box=document.createElement('section');box.className='card scope-card';box.innerHTML=[['Recipient',name(s,p.recipient)],['Amount',money(p.amount,p.currency,p.exponent)],['Source groups',p.groupIds.map(id=>s.groups.find(g=>g.id===id)?.name||id).join('; ')],['Share scope',method.method+' · '+method.currency]].map(([k,v])=>`<div class="scope-row"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');main.insertBefore(box,main.querySelector('.actions'));}if(result?.page==='person')title.textContent='This code belongs to '+name(s,result.id)+'.';if(['invite','invite-already-joined'].includes(page))title.textContent=result.name+' invite.';if(page==='receive-share')title.textContent=name(s,result.owner)+' shared receiving details.';
 const list=main.querySelector('.actions')||document.createElement('div');list.className='actions';list.innerHTML='';if(!list.parentNode)main.append(list);const button=(label,action,ref)=>{const b=document.createElement('button');b.className='btn '+(list.children.length===0?'primary':action==='return'?'text-link':'secondary');b.textContent=label;b.dataset.action='qr-'+action;if(ref)b.dataset.reference=ref;list.append(b);};
 if(!result&&page==='entry')button('Scan a ChopDot code','permission');
 if(!result&&page==='permission'){button('Allow camera','allow');button('Not now','deny');if(fixture)button('Demo camera unavailable','unavailable');}
 else if(!result&&['permission-denied','camera-unavailable'].includes(page))button(page==='permission-denied'?'Try camera permission again':'Try again','permission');
 if(!result&&['entry','scanner-ready','rescan'].includes(page)){const box=document.createElement('section');box.className='card pad';box.innerHTML='<label for="qr-reference">Local prototype reference</label><input id="qr-reference" aria-label="Local prototype reference" placeholder="chopdot-demo:v1:…"><p class="caption">Camera behavior is an explicit fixture. No real camera or external link is opened.</p>';main.insertBefore(box,list);button('Check reference','check');for(const g of s.groups.filter(g=>membershipActive(s,actor,g.id)&&g.id===s.group?.id))for(const p of s.people.filter(p=>p.groupId===g.id&&!g.removedMemberIds?.includes(p.id)))button('Scan demo person '+p.name,'resolve',qrReference('person',p.id));for(const i of s.membership?.invitations.filter(i=>i.status==='pending'&&(i.inviterId===actor||membershipActive(s,actor,i.groupId)))||[])button('Scan demo invitation','resolve',qrReference('invite',i.id));for(const r of s.expansion.shares.filter(r=>r.audience===actor))button('Scan demo receiving share','resolve',qrReference('receive',r.id));}
 else if(['person','own-person','invite','invite-already-joined','receive-share','settlement-match'].includes(page))button(page==='person'?'View person':page==='own-person'?'Back to You':page.startsWith('invite')?'Continue to invite':page==='settlement-match'?'Continue with same payment':'Open receiving details','handoff');else if(page==='offline')button('Try same reference again','recheck');button('Rescan','rescan');button(route.payment?'Back to same payment':'Return to You','return');
 }
 function action(a,el){if(!a.startsWith('qr-'))return false;const{s,actor,route,push,go,owner}=context(),kind=a.slice(3);if(['permission','allow','deny','unavailable'].includes(kind))push({reference:'',page:{permission:'permission',allow:'scanner-ready',deny:'permission-denied',unavailable:'camera-unavailable'}[kind]});else if(kind==='check'||kind==='resolve'){const reference=el.dataset.reference||document.querySelector('#qr-reference').value;const result=resolveQR(s,actor,reference,{paymentId:route.payment});const allowed=['person','own-person','invite','invite-already-joined','receive-share','settlement-match','offline'];push({reference:allowed.includes(result.page)?reference:'',page:result.page});}else if(kind==='rescan')push({reference:'',page:'scanner-ready'});else if(kind==='recheck')push({},true);else if(kind==='return'){if(route.payment)owner('gate-c','#'+new URLSearchParams({page:'payment',id:route.payment}));else owner('gate-d','#page=account');}else if(kind==='handoff'){const r=resolveQR(s,actor,route.reference,{paymentId:route.payment});if(r.page==='person')go('09','person',{person:r.id,group:r.groupId,scope:r.groupId});else if(r.page==='own-person')owner('gate-d','#page=account');else if(r.page.startsWith('invite')&&!r.page.endsWith('expired'))owner('create-join','#'+new URLSearchParams({page: r.page==='invite-already-joined'?'already':'join',invite:r.id}));else if(['receive-share','settlement-match'].includes(r.page))go('14','details',{id:r.id,payment:route.payment,group:route.group});else throw Error('Recheck current audience, session and owning context before handoff.');}else return false;return true;
 }
 return {view,action};
}
